  "Translation draft — qualified review pending. The approved English source is available for comparison.": {
    "ru": "Черновик перевода — ожидается квалифицированная проверка. Утвержденный английский текст доступен для сравнения.",
    "zh-CN": "翻译草稿 — 待专业审核。已批准的英文原件可供对比。",
    "fr": "Brouillon de traduction — révision qualifiée en attente. La source anglaise approuvée est disponible pour comparaison.",
    "es": "Borrador de traducción — revisión cualificada pendiente. La fuente en inglés aprobada está disponible para comparación.",
    "de": "Übersetzungsentwurf — qualifizierte Prüfung ausstehend. Die genehmigte englische Quelle steht zum Vergleich zur Verfügung."
  },
  "Important: This information is not individualized investment, legal, tax or accounting advice. Review the signed agreement for your transaction and seek independent professional advice where appropriate.": {
    "ru": "Важно: эта информация не является индивидуальной инвестиционной, юридической, налоговой или бухгалтерской консультацией. Ознакомьтесь с подписанным соглашением по вашей сделке и при необходимости обратитесь за независимой профессиональной консультацией.",
    "zh-CN": "重要提示：此信息不构成个性化的投资、法律、税务或会计建议。请查阅您交易的签署协议，并在必要时寻求独立的专业建议。",
    "fr": "Important : Cette information ne constitue pas un conseil personnalisé en matière d'investissement, juridique, fiscal ou comptable. Examinez l'accord signé pour votre transaction et demandez conseil à un professionnel indépendant si nécessaire.",
    "es": "Importante: Esta información no constituye asesoramiento financiero, legal, fiscal o contable individualizado. Revise el acuerdo firmado para su transacción y busque asesoramiento profesional independiente cuando sea apropiado.",
    "de": "Wichtig: Diese Informationen stellen keine individuelle Anlage-, Rechts-, Steuer- oder Buchhaltungsberatung dar. Überprüfen Sie die unterzeichnete Vereinbarung für Ihre Transaktion und suchen Sie gegebenenfalls unabhängigen professionellen Rat."
  },
