  "Authenticate locally before the investment request is sent. This device confirmation is separate from account sign-in verification.": {
    "ru": "Пройдите локальную аутентификацию перед отправкой инвестиционного запроса. Это подтверждение на устройстве не связано с проверкой при входе в аккаунт.",
    "zh-CN": "在发送投资请求前进行本地认证。此设备确认独立于账户登录验证。",
    "fr": "Authentifiez-vous localement avant d'envoyer la demande d'investissement. Cette confirmation sur l'appareil est distincte de la vérification de connexion au compte.",
    "es": "Autentíquese localmente antes de enviar la solicitud de inversión. Esta confirmación del dispositivo es independiente de la verificación de inicio de sesión de la cuenta.",
    "de": "Authentifizieren Sie sich lokal, bevor die Investitionsanfrage gesendet wird. Diese Gerätebestätigung ist von der Konto-Anmeldeverifizierung unabhängig."
  },
  "Back to identity documents": {
    "ru": "Вернуться к документам, удостоверяющим личность",
    "zh-CN": "返回身份证件",
    "fr": "Retour aux pièces d'identité",
    "es": "Volver a los documentos de identidad",
    "de": "Zurück zu den Ausweisdokumenten"
  },
  "Balances include available and reserved pending wallet funds. Pending requests are not posted movements; investment profits are separated from returned principal.": {
    "ru": "Баланс включает доступные средства и зарезервированные средства на кошельке. Ожидающие запросы не являются проведенными операциями; инвестиционная прибыль отделена от возвращенной основной суммы.",
    "zh-CN": "余额包含钱包中的可用资金和已预留资金。待处理请求并非已记账动向；投资收益与回流本金分开计算。",
    "fr": "Les soldes incluent les fonds disponibles et les fonds réservés en attente. Les demandes en attente ne sont pas des mouvements enregistrés ; les bénéfices d'investissement sont séparés du capital restitué.",
    "es": "Los saldos incluyen fondos disponibles y fondos reservados pendientes. Las solicitudes pendientes no son movimientos registrados; los beneficios de inversión se separan del capital devuelto.",
    "de": "Die Salden beinhalten verfügbare und reservierte Gelder im Wallet. Ausstehende Anfragen sind keine gebuchten Bewegungen; Investitionsgewinne sind vom zurückgezahlten Kapital getrennt."
  },
