    "fr": "Seuls les détails de l'expédition signalés sont affichés ; aucune position en direct du transporteur n'est déduite.",
    "es": "Solo se muestran los detalles de envío reportados; no se infiere la posición en tiempo real del transportista.",
    "de": "Es werden nur die gemeldeten Versanddetails angezeigt; eine Live-Position des Transportunternehmens wird nicht abgeleitet."
