  "These actions open an editable Support ticket. They do not access, correct, or delete account data automatically; Support will review the request and may verify your identity.": {
    "ru": "Эти действия открывают редактируемую заявку в службу поддержки. Они не открывают доступ, не исправляют и не удаляют данные аккаунта автоматически; служба поддержки рассмотрит запрос и может провести проверку личности.",
    "zh-CN": "这些操作将打开一个可编辑的支持工单。它们不会自动访问、更正或删除账户数据；支持团队将审核请求并可能验证您的身份。",
    "fr": "Ces actions ouvrent un ticket de support modifiable. Elles n'accèdent pas, ne corrigent pas et ne suppriment pas les données du compte automatiquement ; le support examinera la demande et pourra vérifier votre identité.",
    "es": "Estas acciones abren un ticket de soporte editable. No acceden, corrigen ni eliminan datos de la cuenta automáticamente; el equipo de soporte revisará la solicitud y puede verificar su identidad.",
    "de": "Diese Aktionen öffnen ein bearbeitbares Support-Ticket. Sie greifen nicht automatisch auf Kontodaten zu, korrigieren oder löschen diese nicht; der Support prüft die Anfrage und kann Ihre Identität verifizieren."
  },
  "Use existing session controls to review or revoke signed-in devices. Legal documents are shown only when OG Exports provides official content.": {
    "ru": "Используйте существующие элементы управления сеансами для проверки или отзыва доступа к устройствам. Юридические документы отображаются только при наличии официального контента от OG Exports.",
    "zh-CN": "使用现有的会话控件来查看或撤销已登录设备。法律文件仅在 OG Exports 提供官方内容时显示。",
    "fr": "Utilisez les contrôles de session existants pour examiner ou révoquer les appareils connectés. Les documents juridiques ne sont affichés que lorsque OG Exports fournit un contenu officiel.",
    "es": "Utilice los controles de sesión existentes para revisar o revocar dispositivos conectados. Los documentos legales se muestran solo cuando OG Exports proporciona contenido oficial.",
    "de": "Verwenden Sie die vorhandenen Sitzungssteuerelemente, um angemeldete Geräte zu überprüfen oder deren Zugriff zu entziehen. Rechtliche Dokumente werden nur angezeigt, wenn OG Exports offizielle Inhalte bereitstellt."
  },
