  "This device is registered for investor updates. Turning this off revokes its server registration.": {
    "ru": "Это устройство зарегистрировано для получения обновлений инвестора. Отключение приведет к аннулированию его регистрации на сервере.",
    "zh-CN": "此设备已注册接收投资者更新。关闭此项将撤销其服务器注册。",
    "fr": "Cet appareil est enregistré pour recevoir les mises à jour destinées aux investisseurs. Désactiver cette option révoquera son enregistrement sur le serveur.",
    "es": "Este dispositivo está registrado para recibir actualizaciones de inversor. Desactivar esta opción revoca su registro en el servidor.",
    "de": "Dieses Gerät ist für Investoren-Updates registriert. Das Deaktivieren widerruft die Registrierung auf dem Server."
  },
  "This device can show investor updates on the lock screen and in Notification Centre. Your device notification and Focus settings still apply.": {
    "ru": "Это устройство может отображать обновления инвестора на экране блокировки и в Центре уведомлений. Настройки уведомлений и режима «Фокусирование» вашего устройства по-прежнему применяются.",
    "zh-CN": "此设备可在锁定屏幕和通知中心显示投资者更新。您设备的通知和“专注模式”设置仍然适用。",
    "fr": "Cet appareil peut afficher les mises à jour destinées aux investisseurs sur l'écran de verrouillage et dans le Centre de notifications. Les paramètres de notification et de Concentration de votre appareil restent applicables.",
    "es": "Este dispositivo puede mostrar actualizaciones de inversor en la pantalla de bloqueo y en el Centro de notificaciones. Se seguirán aplicando los ajustes de notificación y Concentración de su dispositivo.",
    "de": "Dieses Gerät kann Investoren-Updates auf dem Sperrbildschirm und in der Mitteilungszentrale anzeigen. Ihre Geräte-Benachrichtigungs- und Fokus-Einstellungen bleiben weiterhin gültig."
  },
  "Get wallet, investment, verification and account updates on this device, including while the app is closed. Permission is requested only after you choose to enable them.": {
    "ru": "Получайте обновления по кошельку, инвестициям, верификации и аккаунту на этом устройстве, даже когда приложение закрыто. Разрешение запрашивается только после того, как вы решите их включить.",
    "zh-CN": "在此设备上接收钱包、投资、验证和账户更新，包括在应用程序关闭时。仅在您选择启用后才会请求权限。",
    "fr": "Recevez les mises à jour sur le portefeuille, les investissements, la vérification et le compte sur cet appareil, même lorsque l'application est fermée. L'autorisation n'est demandée qu'après que vous ayez choisi de les activer.",
    "es": "Reciba actualizaciones de la billetera, inversiones, verificación y cuenta en este dispositivo, incluso cuando la aplicación esté cerrada. El permiso se solicitará solo después de que elija activarlas.",
    "de": "Erhalten Sie Updates zu Wallet, Investitionen, Verifizierung und Konto auf diesem Gerät, auch bei geschlossener App. Die Berechtigung wird erst abgefragt, nachdem Sie sich für die Aktivierung entschieden haben."
  },
  "Optional investor updates. Device permission is requested only after you choose to enable them.": {
    "ru": "Дополнительные обновления инвестора. Разрешение устройства запрашивается только после того, как вы решите их включить.",
    "zh-CN": "可选的投资者更新。仅在您选择启用后才会请求设备权限。",
    "fr": "Mises à jour optionnelles pour les investisseurs. L'autorisation de l'appareil n'est demandée qu'après que vous ayez choisi de les activer.",
    "es": "Actualizaciones opcionales para inversores. El permiso del dispositivo se solicitará solo después de que elija activarlas.",
    "de": "Optionale Investoren-Updates. Die Geräteberechtigung wird erst abgefragt, nachdem Sie sich für die Aktivierung entschieden haben."
  },
