    "fr": "La demande de retrait nécessite votre attention. Vérifiez le statut actuel et toute note dans votre historique de retraits.",
    "es": "La solicitud de retiro requiere atención. Revise el estado actual y cualquier nota en su historial de retiros.",
    "de": "Der Auszahlungsantrag erfordert Aufmerksamkeit. Überprüfen Sie den aktuellen Status und eventuelle Hinweise in Ihrem Auszahlungsverlauf."
