  "Your existing wallet must be converted to USD by OG Exports before you can add funds.": {
    "ru": "Ваш текущий кошелек должен быть конвертирован в USD компанией OG Exports, прежде чем вы сможете добавить средства.",
    "zh-CN": "在充值前，您的现有钱包必须先由OG Exports转换为USD。",
    "fr": "Votre portefeuille actuel doit être converti en USD par OG Exports avant de pouvoir ajouter des fonds.",
    "es": "Su billetera actual debe ser convertida a USD por OG Exports antes de que pueda añadir fondos.",
    "de": "Ihr bestehendes Wallet muss von OG Exports in USD umgewandelt werden, bevor Sie Guthaben hinzufügen können."
  },
  "Your existing wallet must be converted to USD by OG Exports before wallet actions can continue. Balances are hidden until then.": {
    "ru": "Ваш текущий кошелек должен быть конвертирован в USD компанией OG Exports для продолжения операций. До этого момента баланс скрыт.",
    "zh-CN": "在进行钱包操作前，您的现有钱包必须先由OG Exports转换为USD。在此之前，余额将隐藏。",
    "fr": "Votre portefeuille actuel doit être converti en USD par OG Exports avant de poursuivre toute action. Le solde est masqué jusqu'à cette opération.",
    "es": "Su billetera actual debe ser convertida a USD por OG Exports antes de continuar con las operaciones. El saldo permanecerá oculto hasta entonces.",
    "de": "Ihr bestehendes Wallet muss von OG Exports in USD umgewandelt werden, bevor Wallet-Aktionen fortgesetzt werden können. Bis dahin bleibt der Kontostand ausgeblendet."
  },
  "Your wallet must be converted to USD on the server before withdrawal. Your balance is hidden until then.": {
    "ru": "Для вывода средств ваш кошелек должен быть конвертирован в USD на сервере. До этого момента ваш баланс скрыт.",
    "zh-CN": "提现前，您的钱包必须先在服务器端转换为USD。在此之前，您的余额将隐藏。",
    "fr": "Votre portefeuille doit être converti en USD sur le serveur avant tout retrait. Votre solde est masqué jusqu'à cette opération.",
    "es": "Su billetera debe convertirse a USD en el servidor antes de realizar retiros. Su saldo permanecerá oculto hasta entonces.",
    "de": "Ihr Wallet muss vor einer Auszahlung serverseitig in USD umgewandelt werden. Bis dahin bleibt Ihr Kontostand ausgeblendet."
  },
  "This withdrawal cannot continue until your app wallet has been converted to USD.": {
    "ru": "Вывод средств невозможен, пока ваш кошелек в приложении не будет конвертирован в USD.",
    "zh-CN": "在您的应用钱包转换为USD之前，无法进行提现。",
    "fr": "Ce retrait ne peut pas aboutir tant que votre portefeuille de l'application n'est pas converti en USD.",
    "es": "Este retiro no puede procesarse hasta que su billetera de la aplicación se convierta a USD.",
    "de": "Diese Auszahlung kann nicht fortgesetzt werden, bis Ihr App-Wallet in USD umgewandelt wurde."
  },
  "Withdrawals are available after the server-side wallet conversion is complete. Your current balance is hidden until then.": {
    "ru": "Вывод средств доступен после завершения конвертации кошелька на сервере. До этого момента ваш текущий баланс скрыт.",
    "zh-CN": "服务器端钱包转换完成后即可进行提现。在此之前，您的当前余额将隐藏。",
    "fr": "Les retraits sont disponibles une fois la conversion du portefeuille sur le serveur terminée. Votre solde actuel est masqué jusqu'à cette opération.",
    "es": "Los retiros están disponibles después de completar la conversión de la billetera en el servidor. Su saldo actual permanecerá oculto hasta entonces.",
    "de": "Auszahlungen sind nach Abschluss der serverseitigen Wallet-Umwandlung verfügbar. Bis dahin bleibt Ihr Kontostand ausgeblendet."
  },
  "Withdrawal terms are not available yet. Refresh your wallet details and try again.": {
    "ru": "Условия вывода средств пока недоступны. Обновите информацию о кошельке и повторите попытку.",
    "zh-CN": "提现条款尚未生效。请刷新钱包详情并重试。",
    "fr": "Les conditions de retrait ne sont pas encore disponibles. Actualisez les détails de votre portefeuille et réessayez.",
    "es": "Las condiciones de retiro aún no están disponibles. Actualice los detalles de su billetera e inténtelo de nuevo.",
    "de": "Auszahlungsbedingungen sind noch nicht verfügbar. Bitte aktualisieren Sie Ihre Wallet-Daten und versuchen Sie es erneut."
  },
  "All OG Exports investor wallets and withdrawals are denominated in USD. The minimum bank payout is USD 100 and the flat USD 2 fee is added to the payout. Existing non-USD wallets must be safely converted by OG Exports before wallet actions are enabled. Processing is estimated at 2 working days; this is not a guarantee.": {
    "ru": "Все инвестиционные кошельки и операции по выводу средств OG Exports деноминированы в USD. Минимальная сумма выплаты на банковский счет составляет 100 USD, к выплате добавляется фиксированная комиссия 2 USD. Существующие кошельки в других валютах должны быть безопасно конвертированы OG Exports перед началом работы. Ориентировочный срок обработки составляет 2 рабочих дня, что не является гарантией.",
    "zh-CN": "所有OG Exports投资者钱包和提现均以USD结算。银行最低提现金额为100 USD，并收取2 USD固定手续费。现有非USD钱包必须由OG Exports安全转换为USD后方可启用钱包功能。预计处理时间为2个工作日，但不做担保。",
    "fr": "Tous les portefeuilles d'investisseurs et les retraits OG Exports sont libellés en USD. Le paiement bancaire minimum est de 100 USD et des frais fixes de 2 USD sont ajoutés au retrait. Les portefeuilles existants non libellés en USD doivent être convertis en toute sécurité par OG Exports avant que les actions du portefeuille ne soient activées. Le traitement est estimé à 2 jours ouvrables ; ceci n'est pas une garantie.",
    "es": "Todas las billeteras de inversores y los retiros de OG Exports están denominados en USD. El pago bancario mínimo es de 100 USD y se añade una tarifa fija de 2 USD al pago. Las billeteras existentes que no estén en USD deben ser convertidas de forma segura por OG Exports antes de habilitar las operaciones de billetera. El procesamiento estimado es de 2 días hábiles; esto no es una garantía.",
    "de": "Alle OG Exports-Investoren-Wallets und Auszahlungen lauten auf USD. Die Mindestauszahlung per Banküberweisung beträgt 100 USD; eine Pauschalgebühr von 2 USD wird auf die Auszahlung erhoben. Bestehende Nicht-USD-Wallets müssen von OG Exports sicher umgewandelt werden, bevor Wallet-Aktionen freigeschaltet werden. Die Bearbeitung dauert voraussichtlich 2 Arbeitstage; dies ist keine Garantie."
  },
