  ". OG Exports supplies the exchange rate when it submits the request; this app does not estimate the wallet debit.": {
    "ru": ". OG Exports предоставляет обменный курс при отправке запроса; приложение не рассчитывает списание со счета.",
    "zh-CN": ". OG Exports 在提交请求时提供汇率；本应用不对钱包扣款金额进行预估。",
    "fr": ". OG Exports fournit le taux de change lors de la soumission de la demande ; cette application n'estime pas le débit du portefeuille.",
    "es": ". OG Exports proporciona el tipo de cambio al enviar la solicitud; esta aplicación no estima el cargo en la billetera.",
    "de": ". OG Exports stellt den Wechselkurs bei Übermittlung der Anfrage bereit; die App schätzt die Abbuchung vom Wallet nicht."
  },
  ". This summary uses your Profile currency, and OG Exports converts the wallet debit at its server rate when you submit.": {
    "ru": ". В этой сводке используется валюта вашего профиля, а OG Exports конвертирует списание со счета по своему серверному курсу в момент отправки.",
    "zh-CN": ". 此摘要使用您的个人资料货币，且 OG Exports 在您提交时按服务器汇率转换钱包扣款金额。",
    "fr": ". Ce récapitulatif utilise la devise de votre profil, et OG Exports convertit le débit du portefeuille au taux de son serveur lors de la soumission.",
    "es": ". Este resumen utiliza la moneda de su perfil, y OG Exports convierte el cargo en la billetera al tipo de cambio de su servidor al momento de enviar.",
    "de": ". Diese Übersicht verwendet Ihre Profilwährung, und OG Exports rechnet die Wallet-Abbuchung zum Zeitpunkt der Übermittlung zum Server-Wechselkurs um."
  },
