  "Tell our team what you need. We’ll help you find a way forward.": {
    "ru": "Сообщите нашей команде, что вам нужно. Мы поможем вам найти решение.",
    "zh-CN": "请告诉我们的团队您的需求。我们将协助您找到解决方案。",
    "fr": "Indiquez vos besoins à notre équipe. Nous vous aiderons à trouver une solution.",
    "es": "Indique a nuestro equipo lo que necesita. Le ayudaremos a encontrar una solución.",
    "de": "Teilen Sie unserem Team mit, was Sie benötigen. Wir helfen Ihnen, eine Lösung zu finden."
  },
