  "The product catalogue is not connected. Please try again later.": {
    "ru": "Каталог продукции не подключен. Пожалуйста, повторите попытку позже.",
    "zh-CN": "产品目录未连接。请稍后再试。",
    "fr": "Le catalogue de produits n'est pas connecté. Veuillez réessayer plus tard.",
    "es": "El catálogo de productos no está conectado. Por favor, inténtelo de nuevo más tarde.",
    "de": "Der Produktkatalog ist nicht verbunden. Bitte versuchen Sie es später erneut."
  },
  "The published risk disclosure could not be loaded.": {
    "ru": "Не удалось загрузить опубликованное уведомление о рисках.",
    "zh-CN": "无法加载已发布的高风险披露。",
    "fr": "La déclaration de risques publiée n'a pas pu être chargée.",
    "es": "No se pudo cargar la declaración de riesgos publicada.",
    "de": "Die veröffentlichte Risikoaufklärung konnte nicht geladen werden."
  },
  "The trade desk will add offers here when they respond.": {
    "ru": "Торговый отдел добавит предложения здесь, когда они ответят.",
    "zh-CN": "交易柜台将在回复后在此处添加报价。",
    "fr": "Le bureau de négoce ajoutera des offres ici lorsqu'ils auront répondu.",
    "es": "El departamento de comercio añadirá ofertas aquí cuando respondan.",
    "de": "Der Handelsschalter wird hier Angebote hinzufügen, sobald eine Antwort vorliegt."
  },
  "There are no countries with listed ports right now.": {
    "ru": "В данный момент нет стран с указанными портами.",
    "zh-CN": "目前没有列出港口的国家。",
    "fr": "Il n'y a actuellement aucun pays avec des ports listés.",
    "es": "Actualmente no hay países con puertos registrados.",
    "de": "Derzeit sind keine Länder mit gelisteten Häfen vorhanden."
  },
  "These help prefill future quote requests. Enter multiple ports or commodities separated by commas.": {
    "ru": "Они помогают автоматически заполнять будущие запросы на котировки. Введите несколько портов или товаров, разделенных запятыми.",
    "zh-CN": "这些信息有助于预填未来的报价请求。输入多个港口或商品，并用逗号分隔。",
    "fr": "Ceci aide à préremplir les futures demandes de devis. Saisissez plusieurs ports ou produits séparés par des virgules.",
    "es": "Esto ayuda a rellenar previamente las futuras solicitudes de presupuesto. Introduzca varios puertos o productos separados por comas.",
    "de": "Dies hilft beim Vorausfüllen zukünftiger Angebotsanfragen. Geben Sie mehrere Häfen oder Waren durch Kommas getrennt ein."
  },
  "These preferences are saved to your buyer account.": {
    "ru": "Эти настройки сохранены в вашей учетной записи покупателя.",
    "zh-CN": "这些偏好已保存到您的买家账户。",
    "fr": "Ces préférences sont enregistrées dans votre compte acheteur.",
    "es": "Estas preferencias se han guardado en su cuenta de comprador.",
    "de": "Diese Einstellungen werden in Ihrem Käuferkonto gespeichert."
  },
  "These settings do not change email preferences or device push delivery.": {
    "ru": "Эти настройки не меняют настройки электронной почты или push-уведомлений на устройстве.",
    "zh-CN": "这些设置不会更改电子邮件偏好或设备推送通知。",
    "fr": "Ces paramètres ne modifient pas les préférences d'e-mail ni les notifications push sur l'appareil.",
    "es": "Estos ajustes no cambian las preferencias de correo electrónico ni la entrega de notificaciones push en el dispositivo.",
    "de": "Diese Einstellungen ändern weder die E-Mail-Einstellungen noch die Push-Benachrichtigungen auf dem Gerät."
  },
  "This app does not transfer money. After paying through your bank, you can submit the reference for OG Exports to verify. Never enter a bank password, PIN, or login code.": {
    "ru": "Это приложение не осуществляет денежные переводы. После оплаты через банк вы можете предоставить реквизиты для проверки в OG Exports. Никогда не вводите пароль от банка, PIN-код или код для входа.",
    "zh-CN": "此应用程序不进行转账。通过银行付款后，您可以提交参考信息供 OG Exports 验证。切勿输入银行密码、PIN 码或登录代码。",
    "fr": "Cette application ne transfère pas d'argent. Après avoir payé via votre banque, vous pouvez soumettre la référence pour vérification par OG Exports. Ne saisissez jamais de mot de passe bancaire, de code PIN ou de code de connexion.",
    "es": "Esta aplicación no realiza transferencias de dinero. Tras pagar a través de su banco, puede enviar la referencia para que OG Exports la verifique. Nunca introduzca su contraseña bancaria, PIN o código de acceso.",
    "de": "Diese App tätigt keine Überweisungen. Nach der Zahlung über Ihre Bank können Sie die Referenz zur Überprüfung durch OG Exports einreichen. Geben Sie niemals Bankpasswörter, PINs oder Anmeldecodes ein."
  },
  "This device will need to sign in again before it can access your buyer account.": {
    "ru": "Этому устройству потребуется повторный вход в систему, прежде чем оно сможет получить доступ к вашей учетной записи покупателя.",
    "zh-CN": "此设备需要重新登录才能访问您的买家账户。",
    "fr": "Cet appareil devra se reconnecter avant de pouvoir accéder à votre compte acheteur.",
    "es": "Este dispositivo deberá volver a iniciar sesión antes de poder acceder a su cuenta de comprador.",
    "de": "Dieses Gerät muss sich erneut anmelden, bevor es auf Ihr Käuferkonto zugreifen kann."
  },
  "This document has no secure access link yet.": {
    "ru": "У этого документа пока нет ссылки на безопасный доступ.",
    "zh-CN": "该文档尚无安全访问链接。",
    "fr": "Ce document ne dispose pas encore de lien d'accès sécurisé.",
    "es": "Este documento aún no tiene un enlace de acceso seguro.",
    "de": "Dieses Dokument verfügt noch über keinen sicheren Zugriffslink."
  },
  "This document is not available yet.": {
    "ru": "Этот документ пока недоступен.",
    "zh-CN": "该文档尚不可用。",
    "fr": "Ce document n'est pas encore disponible.",
    "es": "Este documento aún no está disponible.",
    "de": "Dieses Dokument ist noch nicht verfügbar."
  },
